import React from "react";
import { palette } from "../theme/palette";
import { GarlandSwag, MarigoldStrand } from "../props/Florals";

/*
 * Mandap set, drawn in 1080×1920 scene space. Split into depth pieces so a scene can put
 * each on its own parallax layer: MandapBack → MandapFront (roof, front pillars, drapes).
 */

const Pillar: React.FC<{ x: number; top: number; bottom: number; w: number; tone?: "front" | "back" }> = ({
  x,
  top,
  bottom,
  w,
  tone = "front",
}) => {
  const shaft = tone === "front" ? palette.ivoryLight : "#EADCC0";
  const shadow = tone === "front" ? palette.ivoryShade : "#D8C6A4";
  const rings = [];
  for (let y = top + 120; y < bottom - 80; y += 130) rings.push(y);
  return (
    <g>
      {/* lotus capital */}
      <path
        d={`M${x - w * 0.9} ${top} L${x + w * 0.9} ${top} C${x + w * 0.8} ${top + 22} ${x + w * 0.6} ${top + 34} ${x + w / 2} ${top + 44} L${x - w / 2} ${top + 44} C${x - w * 0.6} ${top + 34} ${x - w * 0.8} ${top + 22} ${x - w * 0.9} ${top} Z`}
        fill="url(#foil)"
      />
      <rect x={x - w / 2} y={top + 44} width={w} height={bottom - top - 88} fill={shaft} />
      <rect x={x - w / 2} y={top + 44} width={w * 0.28} height={bottom - top - 88} fill={shadow} />
      {/* climbing vine */}
      <path
        d={`M${x} ${top + 60} C${x + w * 0.35} ${top + 120} ${x - w * 0.35} ${top + 180} ${x} ${top + 240} S${x + w * 0.35} ${top + 360} ${x} ${top + 420}`}
        fill="none"
        stroke={palette.green}
        strokeWidth={2}
        opacity={0.7}
      />
      {rings.map((y) => (
        <g key={y}>
          <rect x={x - w / 2 - 2} y={y} width={w + 4} height={8} fill="url(#foil-h)" />
          <circle cx={x} cy={y + 4} r={2.4} fill={palette.maroon} />
        </g>
      ))}
      {/* pedestal */}
      <path d={`M${x - w / 2} ${bottom - 44} L${x + w / 2} ${bottom - 44} L${x + w * 0.85} ${bottom} L${x - w * 0.85} ${bottom} Z`} fill="url(#foil)" />
      <rect x={x - w * 0.95} y={bottom - 6} width={w * 1.9} height={10} fill={palette.goldDeep} />
    </g>
  );
};

/** Back pillars (farther, paler, smaller). */
export const MandapBack: React.FC = () => (
  <g>
    <Pillar x={308} top={800} bottom={1400} w={30} tone="back" />
    <Pillar x={772} top={800} bottom={1400} w={30} tone="back" />
    <rect x={290} y={797} width={500} height={6} fill="url(#foil-h)" />
  </g>
);

const Scallops: React.FC<{ x0: number; x1: number; y: number; r: number }> = ({ x0, x1, y, r }) => {
  const n = Math.round((x1 - x0) / (r * 2));
  const step = (x1 - x0) / n;
  let d = `M${x0} ${y}`;
  for (let i = 0; i < n; i++) d += ` A${step / 2} ${r} 0 0 0 ${x0 + (i + 1) * step} ${y}`;
  return (
    <g>
      <path d={`${d} Z`} fill={palette.maroon} />
      <path d={d} fill="none" stroke="url(#foil)" strokeWidth={2.5} />
      {new Array(n + 1).fill(0).map((_, i) => (
        <g key={i}>
          <path d={`M${x0 + i * step} ${y} L${x0 + i * step} ${y + 14}`} stroke={palette.goldLight} strokeWidth={1.2} />
          <path d={`M${x0 + i * step - 3} ${y + 14} L${x0 + i * step + 3} ${y + 14} L${x0 + i * step} ${y + 24} Z`} fill="url(#foil)" />
        </g>
      ))}
    </g>
  );
};

